 13→#[derive(Args)]
 14→pub struct HookHandlerArgs {
 15→    /// The hook name (prepare-commit-msg, post-commit, pre-push)
 16→    pub hook_name: String,
 17→
 18→    /// Extra arguments passed by git to the hook
 19→    #[arg(trailing_var_arg = true)]
 20→    pub args: Vec<String>,
 21→}
 22→
 23→pub fn run(args: &HookHandlerArgs) -> Result<()> {
 24→    // Find the git dir by discovering the repo
 25→    let storage = GitStorage::discover().context("Not inside a Git repository")?;
 26→    let git_dir = storage.repo().path().to_path_buf();
 27→
 28→    match args.hook_name.as_str() {
 29→        "prepare-commit-msg" => {
 30→            // Auto-capture: if enabled and no active session, import current Claude Code session
 31→            maybe_auto_capture(&storage, &git_dir);
 32→
 33→            let msg_file = args
 34→                .args
 35→                .first()
 36→                .map(PathBuf::from)
 37→                .context("prepare-commit-msg: missing message file argument")?;
 38→            hooks::handle_prepare_commit_msg(&msg_file, &git_dir)?;
 39→        }
 40→        "post-commit" => {
 41→            hooks::handle_post_commit(&git_dir)?;
 42→
 43→            // Auto-capture cleanup: if session was auto-created, clean it up
 44→            maybe_auto_capture_cleanup(&storage, &git_dir);
 45→        }
 46→        "pre-push" => {
 47→            maybe_auto_push(&storage);
 48→        }
 49→        other => {
 50→            tracing::debug!("Unknown hook: {other}, ignoring");
 51→        }
 52→    }
 53→
 54→    Ok(())
 55→}
 56→
 57→/// If auto_capture is enabled and no active session exists, discover and import
 58→/// the most recent Claude Code session, then create a temporary ActiveSession
 59→/// so the prepare-commit-msg handler can inject trailers.
 60→fn maybe_auto_capture(storage: &GitStorage, git_dir: &std::path::Path) {
 61→    // Don't interfere with an existing session (e.g. from `engram record`)
 62→    if ActiveSession::load(git_dir).is_some() {
 63→        return;
 64→    }
 65→
 66→    let config = match load_config(storage) {
 67→        Some(c) => c,
 68→        None => return,
 69→    };
 70→
 71→    if !config.auto_capture {
 72→        return;
 73→    }
 74→
 75→    let workdir = match storage.workdir() {
 76→        Some(w) => w.to_path_buf(),
 77→        None => return,
 78→    };
 79→
 80→    // Discover Claude Code session files for this project
 81→    let session_files = match ClaudeCodeImporter::discover_sessions(&workdir) {
 82→        Ok(files) => files,
 83→        Err(e) => {
 84→            tracing::debug!("Auto-capture: failed to discover sessions: {e}");
 85→            return;
 86→        }
 87→    };
 88→
 89→    if session_files.is_empty() {
 90→        tracing::debug!("Auto-capture: no Claude Code sessions found");
 91→        return;
 92→    }
 93→
 94→    // Pick the most recently modified session file
 95→    let newest = session_files
 96→        .into_iter()
 97→        .filter_map(|p| {
 98→            let mtime = std::fs::metadata(&p).ok()?.modified().ok()?;
 99→            Some((p, mtime))
100→        })
101→        .max_by_key(|(_, mtime)| *mtime)
102→        .map(|(p, _)| p);
103→
104→    let session_path = match newest {
105→        Some(p) => p,
106→        None => return,
107→    };
108→
109→    // Import the session
110→    let data = match ClaudeCodeImporter::import_session(&session_path) {
111→        Ok(d) => d,
112→        Err(e) => {
113→            tracing::debug!("Auto-capture: failed to import session: {e}");
114→            return;
115→        }
116→    };
117→
118→    // Check for duplicates — if already imported, reuse the existing engram ID
119→    let engram_id = if let Some(existing_id) = data
120→        .manifest
121→        .source_hash
122→        .as_deref()
123→        .and_then(|h| storage.find_by_source_hash(h))
124→    {
125→        // Already imported this exact snapshot — reuse the ID
126→        existing_id
127→    } else {
128→        // New content — store the engram
129→        let id = data.manifest.id.clone();
130→        match storage.create(&data) {
131→            Ok(_) => {
132→                // Best-effort index update
133→                if let Ok(engine) = SearchEngine::open(storage) {
134→                    let _ = engine.index_engram(&data);
135→                }
136→                tracing::debug!("Auto-capture: imported engram {}", &id.as_str()[..8]);
137→                id
138→            }
139→            Err(e) => {
140→                tracing::debug!("Auto-capture: failed to store engram: {e}");
141→                return;
142→            }
143→        }
144→    };
145→
146→    // Create a temporary ActiveSession so the core handler can inject trailers
147→    let agent = data.manifest.agent.clone();
148→    let mut session = ActiveSession::new(
149→        engram_id,
150→        AgentInfo {
151→            name: agent.name,
152→            model: agent.model,
153→            version: agent.version,
154→        },
155→    );
156→    session.token_usage = data.manifest.token_usage.clone();
157→    session.auto_capture = true;
158→
159→    if let Err(e) = session.save(git_dir) {
160→        tracing::debug!("Auto-capture: failed to save session: {e}");
161→    }
162→}
163→
164→/// After post-commit, if the session was auto-created, update the engram
165→/// with the commit SHA and clean up the session file.
166→fn maybe_auto_capture_cleanup(storage: &GitStorage, git_dir: &std::path::Path) {
167→    let session = match ActiveSession::load(git_dir) {
168→        Some(s) if s.auto_capture => s,
169→        _ => return,
170→    };
171→
172→    // The core post-commit handler already recorded the commit SHA in the session.
173→    // Now read back the session to get the commit, update the engram, and clean up.
174→    let updated = ActiveSession::load(git_dir).unwrap_or(session);
175→
176→    if !updated.commits.is_empty() {
177→        // Re-read the engram, update its git_commits, and re-store it
178→        if let Ok(mut data) = storage.read(updated.engram_id.as_str()) {
179→            for sha in &updated.commits {
180→                if !data.manifest.git_commits.contains(sha) {
181→                    data.manifest.git_commits.push(sha.clone());
182→                }
183→                if !data.lineage.git_commits.contains(sha) {
184→                    data.lineage.git_commits.push(sha.clone());
185→                }
186→            }
187→            // Re-store the updated engram (overwrites the ref)
188→            let _ = storage.create(&data);
189→        }
190→    }
191→
192→    ActiveSession::cleanup(git_dir);
193→    tracing::debug!(
194→        "Auto-capture: finalized engram {} with {} commit(s)",
195→        &updated.engram_id.as_str()[..8],
196→        updated.commits.len()
197→    );
198→}
199→
200→/// If push_on_push is enabled, automatically push engram refs alongside code.
201→/// Uses the git CLI instead of libgit2 so it inherits the user's credential helpers.
202→/// Sets ENGRAM_PUSHING=1 to prevent recursive hook invocation.
203→fn maybe_auto_push(storage: &GitStorage) {
204→    // Guard against recursive invocation: our `git push` triggers pre-push again
205→    if std::env::var_os("ENGRAM_PUSHING").is_some() {
206→        return;
207→    }
208→
209→    let config = match load_config(storage) {
210→        Some(c) => c,
211→        None => return,
212→    };
213→
214→    if !config.push_on_push {
215→        return;
216→    }
217→
218→    let workdir = match storage.workdir() {
219→        Some(w) => w.to_path_buf(),
220→        None => return,
221→    };
222→
223→    match std::process::Command::new("git")
224→        .args(["push", "origin", "refs/engrams/*:refs/engrams/*"])
225→        .env("ENGRAM_PUSHING", "1")
226→        .current_dir(&workdir)
227→        .stdout(std::process::Stdio::piped())
228→        .stderr(std::process::Stdio::piped())
229→        .output()
230→    {
231→        Ok(output) if output.status.success() => {
232→            let stderr = String::from_utf8_lossy(&output.stderr);
233→            let pushed = stderr.lines().filter(|l| l.contains("->")).count();
234→            if pushed > 0 {
235→                eprintln!("engram: pushed {pushed} engram ref(s) to origin");
236→            }
237→        }
238→        Ok(output) => {
239→            let stderr = String::from_utf8_lossy(&output.stderr);
240→            tracing::debug!("Auto-push: git push failed: {stderr}");
241→        }
242→        Err(e) => {
243→            tracing::debug!("Auto-push: failed to run git: {e}");
244→        }
245→    }
246→}
247→
248→/// Load EngramConfig from the repo, returning None on any error.
249→fn load_config(storage: &GitStorage) -> Option<EngramConfig> {
250→    let config = storage.repo().config().ok()?;
251→    EngramConfig::load(&config).ok()
252→}
